  card:'M20 4H4c-1.11 0-1.99.89-1.99 2L2 18c0 1.11.89 2 2 2h16c1.11 0 2-.89 2-2V6c0-1.11-.89-2-2-2zm0 14H4v-6h16v6zm0-10H4V6h16v2z',
  receipt:'M18 17H6v-2h12v2zm0-4H6v-2h12v2zm0-4H6V7h12v2zM3 22l3-2 3 2 3-2 3 2 3-2 3 2V2l-3 2-3-2-3 2-3-2-3 2-3-2v20z',
  calculator:'M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zM7 7h10v2H7V7zm0 4h2v2H7v-2zm4 0h2v2h-2v-2zm4 0h2v2h-2v-2zm-8 4h2v2H7v-2zm4 0h2v2h-2v-2zm4 0h2v2h-2v-2z',
  cash:'M2 4h20v16H2V4zm2 2v12h16V6H4zm8 1a5 5 0 100 10 5 5 0 000-10zm-1 2h2v1h1v2h-2v1h2v2h-1v1h-2v-1h-1v-2h2v-1h-2v-2h1V9z',
  pix:'M12 2l5 5-3.5 3.5a2.12 2.12 0 01-3 0L7 7l5-5zm-6.4 6.4l3.5 3.5a4.1 4.1 0 005.8 0l3.5-3.5L22 12l-3.6 3.6-3.5-3.5a4.1 4.1 0 00-5.8 0l-3.5 3.5L2 12l3.6-3.6zM7 17l3.5-3.5a2.12 2.12 0 013 0L17 17l-5 5-5-5z',
  store:'M20 4H4v2h16V4zm1 10v-2l-1-5H4l-1 5v2h1v6h10v-6h4v6h2v-6h1zM6 18v-4h6v4H6z',
  info:'M11 17h2v-6h-2v6zm1-15a10 10 0 100 20 10 10 0 000-20zm0 18a8 8 0 110-16 8 8 0 010 16zm-1-11h2V7h-2v2z',
  warning:'M1 21h22L12 2 1 21zm12-3h-2v-2h2v2zm0-4h-2v-4h2v4z',
  close:'M18.3 5.71L12 12.01l-6.3-6.3-1.41 1.42 6.3 6.29-6.3 6.3L5.7 21.13l6.3-6.3 6.3 6.3 1.41-1.41-6.3-6.3 6.3-6.29z',
  backspace:'M22 3H7c-.69 0-1.23.35-1.59.88L0 12l5.41 8.12C5.77 20.65 6.31 21 7 21h15c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-3 12.59L17.59 17 14 13.41 10.41 17 9 15.59 12.59 12 9 8.41 10.41 7 14 10.59 17.59 7 19 8.41 15.41 12 19 15.59z',
  camera:'M9 2L7.17 4H4c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2h-3.17L15 2H9zm3 16a5 5 0 110-10 5 5 0 010 10zm0-2a3 3 0 100-6 3 3 0 000 6z',
  photo:'M21 19V5a2 2 0 00-2-2H5a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2zM8.5 13.5l2.5 3L14.5 12l4.5 6H5l3.5-4.5z',
